package dev.koth.gui;

import dev.koth.KoTHPlugin;
import dev.koth.model.Arena;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.AsyncPlayerChatEvent;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import java.util.*;

public final class KoTHGui implements Listener {
    private final KoTHPlugin plugin; private final Map<UUID,String> views=new HashMap<>(); private final Map<UUID,String> chatPrompts=new java.util.concurrent.ConcurrentHashMap<>();
    public KoTHGui(KoTHPlugin plugin){this.plugin=plugin;Bukkit.getPluginManager().registerEvents(this,plugin);}
    private ItemStack item(Material material,String name,String... lore){ItemStack i=new ItemStack(material);ItemMeta m=i.getItemMeta();m.setDisplayName(KoTHPlugin.color(name));m.setLore(Arrays.stream(lore).map(KoTHPlugin::color).toList());i.setItemMeta(m);return i;}
    public void openMain(Player p){Inventory inv=Bukkit.createInventory(null,54,KoTHPlugin.color("&8KoTH &8» &6Management"));int slot=10;for(Arena a:plugin.arenas().values()){inv.setItem(slot,item(Material.BEACON,"&6"+a.name,"&7World: &f"+a.world,"&7Capture: &f"+a.captureSeconds+" seconds","&7Click to configure"));slot++;if(slot==17)slot=19;if(slot>=44)break;}inv.setItem(49,item(Material.EMERALD,"&aCreate arena","&7Use /koth wand then /koth define <name>"));inv.setItem(45,item(Material.CLOCK,"&eSchedules","&7Configure schedules per arena"));p.openInventory(inv);views.put(p.getUniqueId(),"main");}
    public void openArena(Player p,Arena a){Inventory inv=Bukkit.createInventory(null,45,KoTHPlugin.color("&8KoTH &8» &6"+a.name));inv.setItem(10,item(Material.CLOCK,"&eCapture duration: &f"+a.captureSeconds+"s","&7Left click: -5 seconds","&7Right click: +5 seconds"));inv.setItem(11,item(Material.COMPASS,"&bEvent duration: &f"+a.eventSeconds+"s","&7Left click: -60 seconds","&7Right click: +60 seconds"));inv.setItem(12,item(Material.REPEATER,"&dCooldown: &f"+a.cooldownSeconds+"s","&7Left click: -30 seconds","&7Right click: +30 seconds"));inv.setItem(13,item(a.enabled?Material.LIME_DYE:Material.GRAY_DYE,"&aEnabled: &f"+a.enabled,"&7Click to toggle"));inv.setItem(14,item(a.resetOnLeave?Material.REDSTONE:Material.GUNPOWDER,"&cReset on leaving: &f"+a.resetOnLeave,"&7Click to toggle"));inv.setItem(15,item(Material.NAME_TAG,"&6Hologram","&7Set at your location: /koth hologram "+a.name,"&7Edit text in arenas.yml"));inv.setItem(16,item(Material.CHEST,"&aRewards: &f"+a.rewards.size(),"&7Click to add a console command","&7Use %player% and %arena% in commands","&8Manage/remove: /koth reward "+a.name+" list"));inv.setItem(28,item(Material.CLOCK,"&eSchedule: &f"+(a.schedule.isBlank()?"None":a.schedule),"&7Click to enter a weekly schedule","&7Format: MONDAY 18:30","&8Clear: /koth unschedule "+a.name));inv.setItem(30,item(Material.LIME_CONCRETE,"&aForce start","&7Click to start now"));inv.setItem(32,item(Material.BARRIER,"&cStop event","&7Click to stop"));inv.setItem(34,item(Material.PAPER,"&fArena area","&7"+a.world+" | "+a.x1+","+a.y1+","+a.z1,"&7to "+a.x2+","+a.y2+","+a.z2,"&7Redefine using /koth wand and /koth define "+a.name));inv.setItem(40,item(Material.ARROW,"&eBack"));p.openInventory(inv);views.put(p.getUniqueId(),"arena:"+a.name);}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String view=views.get(p.getUniqueId());if(view==null)return;e.setCancelled(true);if(e.getClickedInventory()==null||e.getClickedInventory()!=e.getView().getTopInventory())return;int slot=e.getRawSlot();if(view.equals("main")){if(slot==49){p.closeInventory();plugin.tell(p,"&eRun /koth wand, select two corners, then /koth define <name>.");return;}if(slot==45){p.closeInventory();plugin.tell(p,"&eSchedules: /koth schedule <arena> <DAY> <HH:mm>. Days: MONDAY...SUNDAY.");return;}ItemStack it=e.getCurrentItem();if(it==null||!it.hasItemMeta())return;String n=ChatColor.stripColor(it.getItemMeta().getDisplayName());Arena a=plugin.arenas().get(n.toLowerCase(Locale.ROOT));if(a!=null)openArena(p,a);return;}
        String name=view.substring(6);Arena a=plugin.arenas().get(name);if(a==null){openMain(p);return;}boolean right=e.isRightClick();switch(slot){case 10->a.captureSeconds=Math.max(5,a.captureSeconds+(right?5:-5));case 11->a.eventSeconds=Math.max(60,a.eventSeconds+(right?60:-60));case 12->a.cooldownSeconds=Math.max(0,a.cooldownSeconds+(right?30:-30));case 13->a.enabled=!a.enabled;case 14->a.resetOnLeave=!a.resetOnLeave;case 16->{chatPrompts.put(p.getUniqueId(),"reward:"+a.name);p.closeInventory();p.sendMessage(KoTHPlugin.color("&eType the console reward command in chat. Use %player% and %arena%. Type cancel to abort."));return;}case 28->{chatPrompts.put(p.getUniqueId(),"schedule:"+a.name);p.closeInventory();p.sendMessage(KoTHPlugin.color("&eType a weekly schedule as DAY HH:mm (example: SATURDAY 18:30), or 'none' to clear."));return;}case 30->plugin.service().start(a);case 32->plugin.service().stop(a,true);case 40->{openMain(p);return;}default->{}}plugin.saveArenas();openArena(p,a);}
    @EventHandler public void chatInput(AsyncPlayerChatEvent e){UUID id=e.getPlayer().getUniqueId();String prompt=chatPrompts.remove(id);if(prompt==null)return;e.setCancelled(true);String message=e.getMessage().trim();new BukkitRunnable(){@Override public void run(){Player p=Bukkit.getPlayer(id);if(p==null)return;if(message.equalsIgnoreCase("cancel")){p.sendMessage(KoTHPlugin.color("&cCancelled."));return;}String[] bits=prompt.split(":",2);Arena a=plugin.arenas().get(bits[1].toLowerCase(Locale.ROOT));if(a==null){p.sendMessage(KoTHPlugin.color("&cThat arena no longer exists."));return;}if(bits[0].equals("reward")){a.rewards.add(message);plugin.saveArenas();p.sendMessage(KoTHPlugin.color("&aReward added to "+a.name+"."));}else{if(message.equalsIgnoreCase("none")){a.schedule="";plugin.saveArenas();p.sendMessage(KoTHPlugin.color("&aSchedule cleared."));}else{String[] schedule=message.split("\\s+");try{if(schedule.length!=2)throw new IllegalArgumentException();java.time.DayOfWeek.valueOf(schedule[0].toUpperCase(Locale.ROOT));java.time.LocalTime.parse(schedule[1]);a.schedule=schedule[0].toUpperCase(Locale.ROOT)+" "+schedule[1];plugin.saveArenas();p.sendMessage(KoTHPlugin.color("&aSchedule saved: "+a.schedule));}catch(Exception ex){p.sendMessage(KoTHPlugin.color("&cInvalid schedule. Use DAY HH:mm, e.g. SATURDAY 18:30."));}}}openArena(p,a);}}.runTask(plugin);}
    @EventHandler public void close(InventoryCloseEvent e){views.remove(e.getPlayer().getUniqueId());}
}
